const body = $json.body;
const evento = body.evento;
const resumen = body.resumen || {};
const datos = body.datos || {};

let asunto = '';
let mensaje = '';
let enviar = false;

// ALERTA DE DÉFICIT
if (evento === 'gasto_registrado' || evento === 'test_conexion') {
  if (resumen.saldoNeto < 0) {
    enviar = true;
    asunto = 'ALERTA: Caja en deficit - AgroTech';
    mensaje = '<h2>Alerta AgroTech</h2><p>La caja quedo en <strong>DEFICIT</strong>.</p><ul><li>Saldo: <strong>-$' + Math.abs(resumen.saldoNeto).toLocaleString('es-AR') + '</strong></li><li>Ingresos: $' + (resumen.totalIngresos || 0).toLocaleString('es-AR') + '</li><li>Gastos: $' + (resumen.totalGastos || 0).toLocaleString('es-AR') + '</li></ul><p>Revisa los gastos programados en la app.</p>';
  }
}

// RECORDATORIO DE CHEQUES
if (evento === 'cheques_pendientes' && datos.cheques && datos.cheques.length > 0) {
  const hoy = new Date();
  const proximos = datos.cheques.filter(c => {
    if (!c.fecha) return false;
    const f = new Date(c.fecha + 'T00:00:00');
    const diff = (f - hoy) / (1000 * 60 * 60 * 24);
    return diff >= -1 && diff <= 5 && c.estado === 'normal' && !c.descontado;
  });
  if (proximos.length > 0) {
    enviar = true;
    const total = proximos.reduce((s, c) => s + c.monto, 0);
    asunto = 'Recordatorio: Cheques por cobrar - AgroTech';
    mensaje = '<h2>Recordatorio AgroTech</h2><p>Tenes <strong>' + proximos.length + '</strong> cheque(s) por cobrar pronto:</p><table border="1" cellpadding="8" style="border-collapse:collapse;font-family:Arial;"><tr style="background:#047857;color:white;"><th>#</th><th>Tipo</th><th>Monto</th><th>Vencimiento</th></tr>' + proximos.map((c, i) => '<tr><td>' + (i+1) + '</td><td>' + (c.tipo === 'echeq' ? 'Echeq' : 'Fisico') + '</td><td>$' + c.monto.toLocaleString('es-AR') + '</td><td>' + c.fecha.split('-').reverse().join('/') + '</td></tr>').join('') + '</table><p><strong>Total pendiente: $' + total.toLocaleString('es-AR') + '</strong></p><p>No te olvides de depositarlos.</p>';
  }
}

// INGRESO GRANDE
if (evento === 'ingreso_registrado' && datos.monto > 500000) {
  enviar = true;
  asunto = 'Ingreso grande registrado - AgroTech';
  mensaje = '<h2>Ingreso Grande AgroTech</h2><p>Se registro un ingreso importante:</p><ul><li>Origen: <strong>' + datos.origen + '</strong></li><li>Monto: <strong>$' + datos.monto.toLocaleString('es-AR') + '</strong></li><li>Tipo: ' + datos.tipo + '</li></ul><p>Saldo neto actual: $' + (resumen.saldoNeto || 0).toLocaleString('es-AR') + '</p>';
}

return [{
  json: {
    enviar: enviar === true,
    asunto: asunto,
    mensaje: mensaje,
    evento: evento
  }
}];
